INSERT  IGNORE INTO `states` (`id`, `name`, `slug`, `region`, `is_visible`, `is_default`, `priority`, `sort_order`, `meta_title`, `meta_description`, `meta_keywords`, `heading`, `sub_heading`, `intro_content`, `about_content`, `image`, `og_image`, `gallery`, `faqs`, `content`, `created_at`, `updated_at`, `canonical_url`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_type`, `twitter_card`, `twitter_title`, `twitter_description`, `twitter_image`, `focus_keyword`, `image_alt`, `eyebrow`, `published_at`, `deleted_at`) VALUES (1,'Uttar Pradesh','uttar-pradesh','North India',1,1,100,0,'Wedding & Event Decoration in Uttar Pradesh | Haldi, Mehendi & Balloon Décor - Anuj Kumar Events','Wedding and event decoration across our published service areas in Uttar Pradesh — haldi, mehendi, chunni ceremony, balloon, flower, stage, entry gate and complete wedding setups. Call +91 73020 15048 for booking.','wedding decoration in uttar pradesh, wedding decorator uttar pradesh, haldi decoration up, mehendi decoration up, balloon decoration uttar pradesh, wedding stage decoration up','Wedding & Event Decoration in Uttar Pradesh','Serving every city, tehsil and village of Uttar Pradesh','<p>Anuj Kumar Wedding Event Planners is a full-service wedding and event decoration team working across Uttar Pradesh. From a small haldi function at home to a grand wedding stage, we plan, design and execute every detail.</p><p>We work in more than 400 cities, towns and villages of Uttar Pradesh, including Bulandshahr, Khurja, Sikandrabad, Noida, Greater Noida, Aligarh, Agra, Meerut, Ghaziabad, Kanpur, Lucknow, Varanasi and Prayagraj. Every function gets its own custom theme, fresh flowers, balloons, lighting, entry décor, counters and stage backdrop.</p>','<p>Our team designs every function around a single theme — colour palette, flowers, lighting, drapes and props all matched together, so that everything looks perfect in the photographs. We first understand the size and lighting of the venue, and then finalise the design.</p><p>To book, just share your date, city and budget — we send sample designs, photos and a final quotation within 24 hours. Advance booking locks in your setup date.</p>','https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1600&q=85','https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1600&q=85','[{\"image\": \"https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1600&q=85\", \"title\": \"Wedding Decor\", \"category\": \"Wedding Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Event Decor\", \"category\": \"Event Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Haldi Decor\", \"category\": \"Haldi Decor\"}]','[{\"answer\": \"Yes. We provide wedding and event decoration across Uttar Pradesh, including Bulandshahr, Khurja, Sikandrabad, Noida, Greater Noida, Aligarh, Agra, Meerut, Ghaziabad, Kanpur, Lucknow and all other cities, tehsils and villages.\", \"question\": \"Do you provide wedding decoration in every city of Uttar Pradesh?\"}, {\"answer\": \"Charges depend on the size of the setup, flowers, lighting and theme. A package is available for every budget, from a small home function to a grand banquet stage. Call +91 73020 15048 for an exact quotation.\", \"question\": \"What is the decoration charge in Uttar Pradesh?\"}, {\"answer\": \"Wedding decoration, haldi decoration, mehendi decoration, chunni ceremony, balloon decoration, birthday decoration, flower decoration, stage and backdrop, entry gate decoration, wedding counters, fogg and matka entry and complete event décor.\", \"question\": \"Which services do you offer?\"}, {\"answer\": \"Yes. The theme, colour combination, flowers, balloons, lighting, props and backdrop are all customised as per your preference.\", \"question\": \"Can I customise the theme and colour?\"}, {\"answer\": \"Share your date, city, venue and budget — we send design options and a quotation. Once you confirm in advance, your date is locked in. Call or WhatsApp +91 73020 15048.\", \"question\": \"How can I book a decoration date?\"}]',NULL,'2026-10-19 02:06:39','2026-10-20 23:35:50',NULL,1,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2,'Delhi','delhi','Delhi NCR',0,0,70,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'2026-10-19 02:06:39','2026-11-02 01:40:29',NULL,1,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL);
