INSERT  IGNORE INTO `pages` (`id`, `name`, `slug`, `template`, `meta_title`, `meta_description`, `meta_keywords`, `heading`, `sub_heading`, `intro_content`, `image`, `og_image`, `gallery`, `content`, `faqs`, `is_visible`, `priority`, `sort_order`, `created_at`, `updated_at`, `canonical_url`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_type`, `twitter_card`, `twitter_title`, `twitter_description`, `twitter_image`, `focus_keyword`, `image_alt`, `eyebrow`, `published_at`, `deleted_at`) VALUES (1,'Home','home','default','Wedding & Event Decoration in Uttar Pradesh | Anuj Kumar Wedding Event Planners','Wedding and event decoration by Anuj Kumar Wedding Event Planners - haldi, mehendi, stage, entry, balloon and floral setups across service areas in Uttar Pradesh. Call +91 73020 15048 for booking.','wedding decoration uttar pradesh, wedding decorator near me, haldi decoration, mehendi decoration, balloon decoration, flower decoration, wedding stage decoration','Beautiful Celebrations, <span>Beautifully Decorated</span>','Wedding & Event Decoration in Uttar Pradesh','<p>Thoughtfully designed wedding and event d├⌐cor that turns every celebration into a memorable experience across Uttar Pradesh.</p>','https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=2000&q=85','https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=2000&q=85','[{\"image\": \"https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=2000&q=85\", \"title\": \"Wedding Decor\", \"category\": \"Wedding Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1519225421980-715cb0215aed?auto=format&fit=crop&w=2000&q=85\", \"title\": \"Event Decor\", \"category\": \"Event Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1606800052052-a08af7148866?auto=format&fit=crop&w=2000&q=85\", \"title\": \"Haldi Decor\", \"category\": \"Haldi Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1523438885200-e635ba2c371e?auto=format&fit=crop&w=2000&q=85\", \"title\": \"Mehendi Decor\", \"category\": \"Mehendi Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=2000&q=85\", \"title\": \"Balloon Decor\", \"category\": \"Balloon Decor\"}]','{\"copy\": {\"text_1\": \"Frequently Asked Questions\"}, \"about\": {\"lead\": \"Anuj Kumar Wedding Event Planners creates thoughtfully designed wedding and event decorations that look beautiful, feel personal and make every celebration memorable.\", \"text\": \"From wedding functions and haldi ceremonies to mehendi, chunni ceremonies, birthdays, anniversaries, balloon d├⌐cor, fogg & matka entries and stylish counters, our team creates complete decoration solutions according to your event and vision.\", \"eyebrow\": \"Your Celebration Partner\", \"heading\": \"Turning Your Dreams Into <em>Beautiful Celebrations</em>\", \"location\": \"Sikandrabad, Bulandshahr\", \"cta_label\": \"Plan Your Celebration\"}, \"blogs\": {\"text\": \"Useful decoration ideas and wedding inspiration for your next celebration.\", \"items\": [{\"url\": \"#\", \"image\": \"https://images.unsplash.com/photo-1530103862676-de8c9debad1d?auto=format&fit=crop&w=1000&q=85\", \"title\": \"Top Balloon Decoration Ideas for Birthday Parties\", \"excerpt\": \"Discover stylish balloon arches, garlands and backdrop ideas for a memorable birthday celebration.\", \"category\": \"Balloon Decoration\"}, {\"url\": \"#\", \"image\": \"https://images.unsplash.com/photo-1519225421980-715cb0215aed?auto=format&fit=crop&w=1000&q=85\", \"title\": \"Haldi Decoration Themes That Make Your Function Special\", \"excerpt\": \"Explore vibrant haldi d├⌐cor ideas using flowers, traditional elements, seating and colorful backdrops.\", \"category\": \"Haldi Decoration\"}, {\"url\": \"#\", \"image\": \"https://images.unsplash.com/photo-1511285560929-80b456fea0bc?auto=format&fit=crop&w=1000&q=85\", \"title\": \"How to Plan a Beautiful Mehendi Night Decoration\", \"excerpt\": \"Learn how to choose colours, florals, seating, props and a theme for a memorable mehendi night.\", \"category\": \"Mehendi Decoration\"}], \"eyebrow\": \"Tips & Inspiration\", \"heading\": \"Latest From Our Blog\"}, \"contact\": {\"text\": \"Share your date, city, venue and budget with our team. We will send design options, photos and a final quotation the same day.\", \"eyebrow\": \"Let\'s Plan Your Celebration\", \"heading\": \"Ready to Book Your <em>Decoration?</em>\", \"highlights\": [\"Quick Enquiry\", \"Customized D├⌐cor\", \"Coverage Across Uttar Pradesh\"]}, \"process\": {\"text\": \"Easy planning from the first conversation to the final decoration setup.\", \"steps\": [{\"icon\": \"fa-regular fa-comments\", \"text\": \"Tell us about your event, venue, date and decoration requirements.\", \"title\": \"Share Your Vision\"}, {\"icon\": \"fa-solid fa-palette\", \"text\": \"Select from our ideas or create a customized theme for your event.\", \"title\": \"Choose Your Theme\"}, {\"icon\": \"fa-solid fa-screwdriver-wrench\", \"text\": \"Our team handles the d├⌐cor setup with attention to every detail.\", \"title\": \"We Design & Setup\"}, {\"icon\": \"fa-solid fa-wand-magic-sparkles\", \"text\": \"Relax, celebrate and create beautiful memories with your loved ones.\", \"title\": \"Enjoy Your Celebration\"}], \"eyebrow\": \"Simple Process\", \"heading\": \"How We Make Your Celebration Special\"}, \"packages\": {\"text\": \"Choose a suitable decoration style and customize it according to your event.\", \"items\": [{\"image\": \"https://images.unsplash.com/photo-1530103862676-de8c9debad1d?auto=format&fit=crop&w=1000&q=85\", \"label\": \"Essential Decoration\", \"title\": \"Basic Celebration\", \"featured\": false, \"features\": [\"Essential d├⌐cor setup\", \"Elegant theme options\", \"Ideal for small functions\", \"Professional setup team\"]}, {\"badge\": \"Most Popular\", \"image\": \"https://images.unsplash.com/photo-1519225421980-715cb0215aed?auto=format&fit=crop&w=1000&q=85\", \"label\": \"Customized Decoration\", \"title\": \"Premium Celebration\", \"featured\": true, \"features\": [\"Customized d├⌐cor concept\", \"Premium props & setups\", \"Ideal for family functions\", \"Dedicated setup team\"]}, {\"image\": \"https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1000&q=85\", \"label\": \"Luxury Event Styling\", \"title\": \"Royal Celebration\", \"featured\": false, \"features\": [\"Exclusive theme designs\", \"Luxury d├⌐cor elements\", \"Wedding-ready styling\", \"Complete event d├⌐cor\"]}], \"eyebrow\": \"Flexible Plans\", \"heading\": \"Event Decoration Packages\"}, \"hero_slides\": [{\"tag\": \"Wedding & Event Decoration\", \"image\": \"https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=2200&q=90\", \"heading\": \"Beautiful Celebrations, <span>Beautifully Decorated</span>\", \"highlights\": [\"Elegant Concepts\", \"Custom Decoration\", \"Complete Execution\"], \"description\": \"Thoughtfully designed wedding and event d├⌐cor that transforms every celebration into a memorable experience.\", \"primary_url\": \"#services\", \"primary_label\": \"Explore Services\"}, {\"tag\": \"Stage & Backdrop Decoration\", \"image\": \"https://images.unsplash.com/photo-1519225421980-715cb0215aed?auto=format&fit=crop&w=2200&q=90\", \"heading\": \"Make Your Wedding <span>Stage Shine</span>\", \"highlights\": [\"Premium Backdrops\", \"Designer Lighting\", \"Personalised Themes\"], \"description\": \"Create a stunning focal point with beautifully styled stages, backdrops, lighting and d├⌐cor details designed around your celebration.\", \"primary_url\": \"#services\", \"primary_label\": \"View Stage Designs\"}, {\"tag\": \"Haldi & Mehendi D├⌐cor\", \"image\": \"https://images.unsplash.com/photo-1606800052052-a08af7148866?auto=format&fit=crop&w=2200&q=90\", \"heading\": \"Colourful Traditions, <span>Beautifully Styled</span>\", \"highlights\": [\"Fresh Flowers\", \"Traditional Props\", \"Photo-Ready Setups\"], \"description\": \"Vibrant haldi and mehendi setups with fresh flowers, marigold garlands, props and comfortable seating for the whole family.\", \"primary_url\": \"#gallery\", \"primary_label\": \"See Haldi & Mehendi Ideas\"}, {\"tag\": \"Entry Gate & Counters\", \"image\": \"https://images.unsplash.com/photo-1523438885200-e635ba2c371e?auto=format&fit=crop&w=2200&q=90\", \"heading\": \"Grand Entrances, <span>Memorable Moments</span>\", \"highlights\": [\"Grand Entry Gates\", \"Themed Counters\", \"Fresh Flower Work\"], \"description\": \"Impressive entry gates, welcome counters and stylish food counters that set the tone for your entire celebration.\", \"primary_url\": \"#services\", \"primary_label\": \"Explore Entry D├⌐cor\"}, {\"tag\": \"Complete Event Solutions\", \"image\": \"https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=2200&q=90\", \"heading\": \"From Concept To <span>Celebration</span>\", \"highlights\": [\"Single Point of Contact\", \"On-Time Setup\", \"Transparent Pricing\"], \"description\": \"One team for the complete function ΓÇö decoration, lighting, stage, flowers, balloons and on-time execution.\", \"primary_url\": \"#contact\", \"primary_label\": \"Plan Your Event\"}], \"trust_items\": [{\"icon\": \"fa-regular fa-lightbulb\", \"label\": \"Creative\", \"title\": \"Designs\"}, {\"icon\": \"fa-solid fa-palette\", \"label\": \"Fully\", \"title\": \"Customized Themes\"}, {\"icon\": \"fa-regular fa-clock\", \"label\": \"Reliable\", \"title\": \"On-Time Setup\"}, {\"icon\": \"fa-solid fa-gem\", \"label\": \"Finest\", \"title\": \"Premium Quality\"}, {\"icon\": \"fa-solid fa-heart\", \"label\": \"From Concept To Celebration\", \"title\": \"Complete Event Solutions\"}], \"services_cta\": {\"text\": \"Tell us about your occasion, theme and requirements. We\'ll create a decoration plan that feels uniquely yours and beautifully reflects your celebration.\", \"button\": \"Get Your Custom Quote\", \"eyebrow\": \"Let\'s Create Something Beautiful\", \"heading\": \"Turn Your Next Event Into A <em>Grand Celebration</em>\", \"occasions\": [{\"icon\": \"fa-solid fa-ring\", \"label\": \"Weddings\"}, {\"icon\": \"fa-solid fa-cake-candles\", \"label\": \"Birthdays\"}, {\"icon\": \"fa-solid fa-heart\", \"label\": \"Engagements\"}, {\"icon\": \"fa-solid fa-baby\", \"label\": \"Baby Showers\"}, {\"icon\": \"fa-solid fa-champagne-glasses\", \"label\": \"Anniversaries\"}, {\"icon\": \"fa-solid fa-building\", \"label\": \"Corporate Events\"}]}, \"gallery_heading\": {\"text\": \"Explore beautifully styled wedding stages, haldi and mehendi setups, birthdays, flower decoration and special celebration d├⌐cor.\", \"eyebrow\": \"Our Recent Work\", \"heading\": \"Wedding & Event <em>Decoration Gallery</em>\"}, \"hero_highlights\": [\"Wedding & Event Specialists\", \"Custom Themes\", \"On-Time Setup\", \"Across Uttar Pradesh\"], \"services_heading\": {\"text\": \"From intimate family functions to grand wedding celebrations, we create thoughtfully styled d├⌐cor that brings your vision beautifully to life.\", \"eyebrow\": \"What We Do\", \"heading\": \"Our Wedding & Event <em>Decoration Services</em>\"}}','[{\"answer\": \"Yes. We provide wedding and event decoration in every city, town and village of Uttar Pradesh, including Bulandshahr, Khurja, Sikandrabad, Noida, Greater Noida, Aligarh, Meerut, Agra, Kanpur and Lucknow.\", \"question\": \"Do you provide wedding decoration across Uttar Pradesh?\"}, {\"answer\": \"The price depends on the size of the setup, flowers, lighting and theme. We have packages for every budget. Call or WhatsApp +91 73020 15048 for an exact quotation.\", \"question\": \"What is the price of wedding decoration?\"}, {\"answer\": \"Yes, subject to availability. If you confirm in the morning, a same-day or next-day setup can be arranged for most functions.\", \"question\": \"Do you take same-day decoration bookings?\"}, {\"answer\": \"Absolutely. The theme, colours, flowers, balloons, drapes, lighting and props are all decided as per your preference and venue.\", \"question\": \"Can I customise the theme and colours?\"}, {\"answer\": \"Share your date, city, venue and budget on WhatsApp. We send design photos and a quotation the same day. Once you confirm, your date is blocked.\", \"question\": \"How do I book a date?\"}]',1,100,10,'2026-10-19 05:01:20','2026-11-06 02:09:27',NULL,1,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(2,'About Us','about-us','default','About Us | Anuj Kumar Wedding Event Planners','Learn about Anuj Kumar Wedding Event Planners ΓÇö a professional wedding and event decoration team serving Agra, Aligarh, Bulandshahr, Gautam Buddh Nagar, Ghaziabad, Hapur, Meerut and Mathura.','about anuj kumar wedding event planners, wedding decorator uttar pradesh, event decoration team','Wedding & Event Decoration <span>Designed Around Your Celebration</span>',NULL,'Anuj Kumar Wedding Event Planners creates elegant, creative and customized wedding and event decoration experiences across Uttar Pradesh. We bring together thoughtful d├⌐cor, beautiful themes and organized execution for celebrations that deserve to be remembered.','https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1600&q=85','https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1600&q=85','[{\"image\": \"https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1600&q=85\", \"title\": \"Wedding Decor\", \"category\": \"Wedding Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Event Decor\", \"category\": \"Event Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1507504031003-b417219a0fde?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Haldi Decor\", \"category\": \"Haldi Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1530103862676-de8c9debad1d?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Mehendi Decor\", \"category\": \"Mehendi Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1519225421980-715cb0215aed?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Balloon Decor\", \"category\": \"Balloon Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1478146896981-b80fe463b330?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Birthday Decor\", \"category\": \"Birthday Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1490750967868-88aa4486c946?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Flower Decor\", \"category\": \"Flower Decor\"}]','{\"copy\": {\"text_1\": \"Anuj Kumar Wedding Event Planners\", \"text_2\": \"Years of Creative\\r\\n                                Event Experience\", \"text_3\": \"About Our Wedding & Event Decoration Company\", \"text_4\": \"We Turn Celebration Spaces Into\", \"text_5\": \"Theme ideas planned around your occasion.\", \"text_6\": \"D├⌐cor adapted to your venue and preferences.\", \"text_7\": \"Planned setup with attention to timing.\", \"text_8\": \"Every celebration gets individual attention.\", \"text_9\": \"Discuss Your Event With Us\", \"text_10\": \"Why Choose Anuj Kumar Wedding Event Planners\", \"text_11\": \"A beautiful event starts with understanding the\\r\\n                    occasion. We combine creative ideas, customized\\r\\n                    styling and organized execution to create a\\r\\n                    decoration experience that feels personal.\", \"text_12\": \"Creative Decoration Ideas\", \"text_13\": \"Attractive wedding and event d├⌐cor concepts\\r\\n                            planned according to your occasion, venue\\r\\n                            and celebration style.\", \"text_14\": \"Colors, flowers, balloons, backdrops and\\r\\n                            decorative elements can be styled around\\r\\n                            your preferences.\", \"text_15\": \"We focus on preparation and coordination\\r\\n                            to help keep your decoration setup aligned\\r\\n                            with the event schedule.\", \"text_16\": \"Celebration-Focused Service\", \"text_17\": \"Every wedding, ceremony and family event\\r\\n                            is different, so we keep our service\\r\\n                            personal and detail-focused.\", \"text_18\": \"Our Approach To Wedding & Event D├⌐cor\", \"text_19\": \"Every Detail Matters\\r\\n                        When You\'re Celebrating\", \"text_20\": \"Our work is centered around creating attractive,\\r\\n                        coordinated and celebration-ready spaces. We\\r\\n                        pay attention to the visual details that help\\r\\n                        transform an ordinary venue into a memorable\\r\\n                        celebration space.\", \"text_21\": \"Whether you are planning a traditional wedding,\\r\\n                        Haldi, Mehendi, Chunni ceremony, birthday,\\r\\n                        family function or complete event d├⌐cor,\\r\\n                        we work to make the decoration complement\\r\\n                        the occasion beautifully.\", \"text_22\": \"Elegant Finishing Details\", \"text_23\": \"Traditional & Modern Styles\", \"text_24\": \"D├⌐cor With\\r\\n                            Character\", \"text_25\": \"Designed to complement\\r\\n                            your celebration.\", \"text_26\": \"Wedding & Event Decoration Services\", \"text_27\": \"Creative balloon arches, garlands,\\r\\n                                themed backdrops and attractive party\\r\\n                                decoration setups.\", \"text_28\": \"Bright and colorful Haldi decoration\\r\\n                                with vibrant themes and traditional\\r\\n                                celebration styling.\", \"text_29\": \"Beautiful Mehendi d├⌐cor with colorful\\r\\n                                themes, florals, seating and decorative props.\", \"text_30\": \"Chunni Ceremony Decoration\", \"text_31\": \"Elegant traditional and contemporary\\r\\n                                d├⌐cor for beautiful Chunni ceremony\\r\\n                                celebrations.\", \"text_32\": \"Special decorative elements and effects\\r\\n                                designed to add character to celebrations.\", \"text_33\": \"Stylish welcome, food, dessert and\\r\\n                                themed counters for wedding events.\", \"text_34\": \"Floral decoration for stages, entrances,\\r\\n                                backdrops, tables and wedding venues.\", \"text_35\": \"Complete event styling from d├⌐cor concepts\\r\\n                                and backdrops to finishing details.\", \"text_36\": \"Looking for a customized decoration setup?\", \"text_37\": \"Our Wedding & Event Decoration Process\", \"text_38\": \"We follow a simple and organized approach to understand\\r\\n                    your requirements, plan the d├⌐cor and prepare a\\r\\n                    celebration-ready setup.\", \"text_39\": \"We discuss your occasion, venue, theme,\\r\\n                        preferences and decoration requirements.\", \"text_40\": \"We organize d├⌐cor elements, layouts, colors,\\r\\n                        props and the overall visual direction.\", \"text_41\": \"The planned concept is transformed into a\\r\\n                        coordinated and attractive event setup.\", \"text_42\": \"You enjoy your special occasion while the\\r\\n                        d├⌐cor becomes part of the celebration.\", \"text_43\": \"Plan Your Celebration With Us\", \"text_44\": \"Let\'s Create A\\r\\n                        Celebration Worth Remembering\", \"text_45\": \"Tell us about your wedding, Haldi, Mehendi,\\r\\n                        birthday, ceremony or special event. Share your\\r\\n                        venue, date and decoration requirements and\\r\\n                        let\'s discuss the right d├⌐cor concept for you.\"}, \"about_story\": \"<p>Anuj Kumar Wedding Event Planners is a wedding and event decoration company based in <strong>{address}</strong>. We specialize in creating attractive and personalized d├⌐cor setups for weddings, ceremonies, birthdays, family functions and special celebrations.</p><p>We believe that decoration should complement the occasion rather than simply fill a space. That is why our approach considers the venue, theme, colors, occasion and personal preferences while planning the overall d├⌐cor experience.</p><p>From <a href=\\\"/services/haldi-decoration\\\">Haldi Decoration</a> and <a href=\\\"/services/mehendi-decoration\\\">Mehendi Decoration</a> to <a href=\\\"/services/flower-decoration\\\">Flower Decoration</a>, <a href=\\\"/services/balloon-decoration\\\">Balloon Decoration</a>, Chunni Ceremony Decoration, Wedding Counters, Fogg & Matka and Complete Event D├⌐cor, we focus on creating a coordinated look for every celebration.</p>\"}','[]',1,70,20,'2026-10-19 05:01:21','2026-11-06 02:09:27',NULL,1,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(3,'Services','services','default','Wedding & Event Decoration Services | Anuj Kumar Wedding Event Planners','Explore our complete range of wedding and event decoration services ΓÇö haldi, mehendi, chunni ceremony, balloon, flower, stage, entry gate, wedding counters and complete event d├⌐cor.','wedding decoration services, haldi decoration, mehendi decoration, balloon decoration, flower decoration, stage decoration','Complete Decoration Services <span>For Every Celebration</span>',NULL,'Explore our complete range of wedding and event decoration services, thoughtfully designed for Haldi, Mehendi, Chunni ceremonies, weddings, parties and special events. Choose the decoration style that perfectly matches your celebration.','https://images.unsplash.com/photo-1530103862676-de8c9debad1d?auto=format&fit=crop&w=1200&q=85','https://images.unsplash.com/photo-1530103862676-de8c9debad1d?auto=format&fit=crop&w=1200&q=85','[{\"image\": \"https://images.unsplash.com/photo-1530103862676-de8c9debad1d?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Wedding Decor\", \"category\": \"Wedding Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1519225421980-715cb0215aed?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Event Decor\", \"category\": \"Event Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Haldi Decor\", \"category\": \"Haldi Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1519167758481-83f550bb49b3?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Mehendi Decor\", \"category\": \"Mehendi Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Balloon Decor\", \"category\": \"Balloon Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1523438885200-e635ba2c371e?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Birthday Decor\", \"category\": \"Birthday Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1511285560929-80b456fea0bc?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Flower Decor\", \"category\": \"Flower Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1478146896981-b80fe463b330?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Stage Decor\", \"category\": \"Stage Decor\"}]','{\"copy\": {\"text_1\": \"Wedding & Event Decoration Services\", \"text_2\": \"Everything You Need For A\", \"text_3\": \"Beautifully Decorated Celebration\", \"text_4\": \"From intimate family functions to complete wedding\\r\\n                    celebrations, we provide professional decoration solutions\\r\\n                    with attention to theme, colour, venue and every important\\r\\n                    visual detail.\", \"text_5\": \"WEDDING & EVENT DECORATION\", \"text_6\": \"Select a service to explore its decoration possibilities,\\r\\n                    styling ideas and event-specific solutions.\", \"text_7\": \"Complete Celebration Experience\", \"text_8\": \"Our approach is focused on creating a coordinated\\r\\n                        visual experience. From colours and flowers to\\r\\n                        backdrops, counters and finishing details, every\\r\\n                        element is planned to work beautifully together.\", \"text_9\": \"Custom decoration requirements\", \"text_10\": \"Tell us about your event, date, venue and decoration\\r\\n                        requirements. We will help you plan a beautiful setup\\r\\n                        for your special occasion.\"}}','[]',1,90,30,'2026-10-19 05:01:21','2026-11-06 02:09:27',NULL,1,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL),(4,'Gallery','gallery','default','Wedding & Event Decoration Gallery | Anuj Kumar Wedding Event Planners','Browse photos of our wedding, haldi, mehendi, birthday and event decoration setups. Real d├⌐cor work from our published service areas in Uttar Pradesh.','wedding decoration gallery, decoration photos, haldi decoration images, wedding stage photos','Beautiful Celebrations <span>Beautifully Decorated</span>',NULL,'Explore our collection of beautiful wedding and event decoration ideas, featuring elegant wedding stages, Haldi setups, Mehendi d├⌐cor, floral arrangements, balloon decoration and complete event styling for memorable celebrations.','https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1200&q=85','https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1200&q=85','[{\"image\": \"https://images.unsplash.com/photo-1519741497674-611481863552?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Wedding Decor\", \"category\": \"Wedding Decor\"}, {\"image\": \"https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85\", \"title\": \"Event Decor\"