/*!40000 ALTER TABLE `posts` DISABLE KEYS */;
INSERT  IGNORE INTO `posts` (`id`, `post_category_id`, `title`, `slug`, `excerpt`, `body`, `author`, `reading_minutes`, `image`, `og_image`, `gallery`, `is_visible`, `is_featured`, `priority`, `sort_order`, `published_at`, `meta_title`, `meta_description`, `meta_keywords`, `canonical_url`, `robots_index`, `robots_follow`, `og_title`, `og_description`, `og_type`, `twitter_card`, `twitter_title`, `twitter_description`, `twitter_image`, `focus_keyword`, `image_alt`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,1,'Haldi Decoration Ideas for a Colourful Function','haldi-decoration-ideas','Practical ideas for planning a colourful haldi setup with flowers, seating and a photo-friendly backdrop.','<p>A haldi function is one of the most colourful parts of a wedding. Choose a clear focal point, comfortable seating for the family and a backdrop that photographs well. Marigold, fresh flowers and fabric drapes are a simple starting point.</p><p>Keep the décor practical: leave enough space for guests to move, protect the flooring and confirm the setup time with the venue.</p>',NULL,4,'https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85','https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85','[]',1,1,50,10,'2026-11-02 01:40:31','Haldi Decoration Ideas for a Colourful Function','Practical ideas for planning a colourful haldi setup with flowers, seating and a photo-friendly backdrop.',NULL,NULL,1,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'haldi decoration ideas for a colourful function',NULL,'2026-11-02 01:40:31','2026-11-02 01:40:31',NULL),(2,2,'How to Plan a Mehendi Night Decoration','plan-mehendi-night-decoration','A simple planning checklist for mehendi night décor, seating, lighting and a comfortable guest area.','<p>Mehendi night works best when the décor is comfortable and easy to use. Plan the seating first, then add lighting and a backdrop. Keep the mehendi artist area well lit and leave a clear path for guests.</p>',NULL,4,'https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85','https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85','[]',1,1,50,20,'2026-11-02 01:40:31','How to Plan a Mehendi Night Decoration','A simple planning checklist for mehendi night décor, seating, lighting and a comfortable guest area.',NULL,NULL,1,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'how to plan a mehendi night decoration',NULL,'2026-11-02 01:40:31','2026-11-02 01:40:31',NULL),(3,3,'Balloon Decoration Ideas for Birthday Parties','balloon-decoration-birthday-ideas','Balloon arches, garlands and backdrop ideas for a birthday celebration at home or at a venue.','<p>Balloon decoration can be as simple or as elaborate as you like. Start with one focal wall, choose a colour palette and add a few larger statement balloons. Confirm the ceiling height and whether the venue allows tape or fixing points.</p>',NULL,3,'https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85','https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85','[]',1,0,50,30,'2026-11-02 01:40:31','Balloon Decoration Ideas for Birthday Parties','Balloon arches, garlands and backdrop ideas for a birthday celebration at home or at a venue.',NULL,NULL,1,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'balloon decoration ideas for birthday parties',NULL,'2026-11-02 01:40:31','2026-11-02 01:40:31',NULL),(4,4,'Wedding Decoration Planning Checklist','wedding-decoration-planning-checklist','What to confirm before booking a wedding decoration team: venue, timings, theme, flowers and setup access.','<p>Before booking a decoration team, confirm the venue, the setup and removal timings, what the venue already provides and which areas you want to decorate. Share reference photos and agree on the final scope in writing.</p>',NULL,5,'https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85','https://images.unsplash.com/photo-1464366400600-7168b8af9bc3?auto=format&fit=crop&w=1200&q=85','[]',1,0,50,40,'2026-11-02 01:40:31','Wedding Decoration Planning Checklist','What to confirm before booking a wedding decoration team: venue, timings, theme, flowers and setup access.',NULL,NULL,1,1,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'wedding decoration planning checklist',NULL,'2026-11-02 01:40:31','2026-11-02 01:40:31',NULL);
