/*!40000 ALTER TABLE `faqs` DISABLE KEYS */;
INSERT  IGNORE INTO `faqs` (`id`, `question`, `answer`, `category`, `scope`, `is_visible`, `sort_order`, `created_at`, `updated_at`, `deleted_at`) VALUES (1,'Which areas do you serve?','We currently accept decoration bookings in Agra, Aligarh, Bulandshahr, Gautam Buddh Nagar (Noida and Greater Noida), Ghaziabad, Hapur, Meerut and Mathura.','booking','global',1,10,'2026-11-02 01:40:31','2026-11-02 01:40:31',NULL),(2,'How do I book a decoration date?','Share your event date, city, venue and requirements through the enquiry form, phone or WhatsApp. The team will confirm availability and share a quotation.','booking','global',1,20,'2026-11-02 01:40:31','2026-11-02 01:40:31',NULL),(3,'Can the theme and colours be customised?','Yes. The theme, colour palette, flowers, balloons, lighting and props are planned around your venue and preferences.','decoration','global',1,30,'2026-11-02 01:40:31','2026-11-02 01:40:31',NULL),(4,'Do you provide complete event decoration?','Yes. Complete event decoration can combine the stage, entrance, seating, counters, flowers and lighting in one coordinated setup.','decoration','global',1,40,'2026-11-02 01:40:31','2026-11-02 01:40:31',NULL),(5,'How is the decoration price decided?','The price depends on the venue size, number of decoration elements, flowers, lighting and setup time. A written quotation is shared after the requirements are confirmed.','pricing','global',1,50,'2026-11-02 01:40:31','2026-11-02 01:40:31',NULL),(6,'Do you take same-day bookings?','Same-day bookings depend on team availability. Contact the team as early as possible with the event date and venue.','booking','global',1,60,'2026-11-02 01:40:31','2026-11-02 01:40:31',NULL);
